# parameter_rows ----
## Setup ----
# von Bertalanffy growth on data_big with only L1, L2 and k estimated, and no
# recruitment process. The starting values are near the estimates, so the
# Hessian there is positive definite and the sdreport at the start gives
# standard errors without a fit.
data("data_big")
data_von_bertalanffy <- data_big |>
  dplyr::filter(type != "weight_at_age") |>
  FIMSFrame()
growth_parameters <- setup_default_parameters(data = data_von_bertalanffy) |>
  dplyr::mutate(
    estimation_type = dplyr::if_else(
      module_name == "Growth", estimation_type, "constant"
    ),
    distribution_type = dplyr::if_else(
      module_name == "Recruitment", NA_character_, distribution_type
    ),
    distribution = dplyr::if_else(
      module_name == "Recruitment", NA_character_, distribution
    ),
    value = dplyr::case_when(
      module_name == "Growth" & label == "mean_length_young" ~ 289,
      module_name == "Growth" & label == "mean_length_old" ~ 835,
      module_name == "Growth" & label == "growth_coefficient" ~ 0.236,
      .default = value
    )
  )

# The mean_length_old row of get_estimates(), with the sdreport at the
# starting values, and the SD of L2 = L1 + exp(x) over many draws of the
# working-scale estimates of log L1 (when estimated) and x = log(L2 - L1).
# The draws check the delta method without using it.
mean_length_old_at_start <- function(parameters) {
  input <- initialize_fims(parameters = parameters, data = data_von_bertalanffy)
  obj <- get_obj(fit_fims(input, optimize = FALSE, get_sd = FALSE))
  sdreport <- RTMB::sdreport(obj)
  is_length <- grepl("mean_length", names(sdreport[["par.fixed"]]))
  mean <- sdreport[["par.fixed"]][is_length]
  set.seed(20261119)
  n_draws <- 1e6
  draws <- matrix(stats::rnorm(n_draws * length(mean)), n_draws) %*%
    chol(sdreport[["cov.fixed"]][is_length, is_length, drop = FALSE]) +
    rep(mean, each = n_draws)
  colnames(draws) <- names(mean)
  mean_length_young <- if ("Growth.log_mean_length_young" %in% names(mean)) {
    exp(draws[, "Growth.log_mean_length_young"])
  } else {
    289
  }
  list(
    row = get_estimates(
      FIMSFit(input = input, obj = obj, sdreport = sdreport)
    ) |>
      dplyr::filter(module_name == "Growth", label == "mean_length_old"),
    draw_sd = stats::sd(
      mean_length_young + exp(draws[, "Growth.log_difference_mean_length_old"])
    )
  )
}

## IO correctness ----
test_that("`parameter_rows()` works with correct inputs", {
  for (young in c("fixed_effects", "constant")) {
    mean_length_old <- growth_parameters |>
      dplyr::mutate(estimation_type = dplyr::if_else(
        module_name == "Growth" & label == "mean_length_young",
        young, estimation_type
      )) |>
      mean_length_old_at_start()
    #' @description Test that `parameter_rows()` reports L2 on the natural scale when it is estimated as log(L2 - L1), with L1 estimated or constant.
    expect_equal(
      object = mean_length_old[["row"]][["estimated"]],
      expected = 835
    )
    #' @description Test that the standard error of L2, estimated as log(L2 - L1), matches the spread of its back-transformed draws, using the covariance with log L1 when L1 is estimated.
    expect_equal(
      object = mean_length_old[["row"]][["uncertainty"]],
      expected = mean_length_old[["draw_sd"]],
      tolerance = 0.01
    )
  }
})

